<?php
require __DIR__.'/app/bootstrap.php';
if(empty($_SESSION['customer_id'])){header('Location: '.url('account.php'));exit;}if(empty($_SESSION['cart'])){header('Location: '.url('cart.php'));exit;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$note=trim($_POST['note']??'');
if(!$name||!$phone||!$address||!$city){$error='Please complete your name, phone, address and city.';}else{try{$pdo=db();$pdo->beginTransaction();$cart=$_SESSION['cart'];$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,price,stock,status FROM products WHERE id IN ($marks) FOR UPDATE");$s->execute($ids);$products=$s->fetchAll();if(count($products)!==count($ids))throw new RuntimeException('One or more cart products are unavailable.');$total=0;$lines=[];foreach($products as $p){$qty=(int)$cart[$p['id']];if($p['status']!=='active'||$qty<1||$qty>(int)$p['stock'])throw new RuntimeException('Stock changed for '.$p['name'].'. Please review your cart.');$total+=(float)$p['price']*$qty;$lines[]=[$p,$qty];}
$orderNo='NT'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare("INSERT INTO orders(customer_id,order_number,customer_name,phone,address,city,note,subtotal,total,status,payment_method,payment_status) VALUES(?,?,?,?,?,?,?,?,?,'pending','cash_on_delivery','unpaid')");$s->execute([$_SESSION['customer_id'],$orderNo,$name,$phone,$address,$city,$note,$total,$total]);$orderId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)');$upd=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');foreach($lines as [$p,$qty]){$ins->execute([$orderId,$p['id'],$p['name'],$p['price'],$qty,$p['price']*$qty]);$upd->execute([$qty,$p['id'],$qty]);if($upd->rowCount()!==1)throw new RuntimeException('Stock changed while placing your order.');}$pdo->commit();unset($_SESSION['cart']);header('Location: '.url('order-success.php?order='.rawurlencode($orderNo)));exit;
}catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$t instanceof PDOException?'We could not place your order. Please try again.':$t->getMessage();}}}
$s=db()->prepare('SELECT name,phone FROM customers WHERE id=?');$s->execute([$_SESSION['customer_id']]);$customer=$s->fetch()?:['name'=>'','phone'=>''];$ids=array_map('intval',array_keys($_SESSION['cart']));$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT id,name,price FROM products WHERE id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();$total=0;foreach($items as $p)$total+=(float)$p['price']*(int)$_SESSION['cart'][$p['id']];
$pageTitle='Checkout — NEXT TECH';require __DIR__.'/includes/header.php';?>
<section class="page-intro"><span class="eyebrow">FINAL STEP</span><h1>Checkout</h1><p>Cash on delivery. Our team will contact you to confirm your order.</p></section><?php if($error):?><p class="form-error"><?=e($error)?></p><?php endif;?>
<div class="checkout-layout"><form class="admin-panel form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full Name<input name="name" required value="<?=e($customer['name'])?>"></label><label>Phone Number<input name="phone" required value="<?=e($customer['phone'])?>" placeholder="01XXXXXXXXX"></label><label class="full">Delivery Address<textarea name="address" rows="3" required></textarea></label><label>City / District<input name="city" required></label><label class="full">Order Note (optional)<textarea name="note" rows="2"></textarea></label><div class="full"><button class="btn btn-primary">Place Order — <?=money($total)?></button></div></form><aside class="admin-panel"><h2>Order Summary</h2><?php foreach($items as $p):?><p><?=e($p['name'])?> × <?=(int)$_SESSION['cart'][$p['id']]?> <strong style="float:right"><?=money($p['price']*$_SESSION['cart'][$p['id']])?></strong></p><?php endforeach;?><hr><h3>Total: <?=money($total)?></h3><p class="notice">Payment method: Cash on Delivery</p></aside></div><?php require __DIR__.'/includes/footer.php';?>